/* Authored v666 project workspace finder. */
.bubble-dock #worker-finder-bubble{display:grid;place-items:center}
.bubble-dock #worker-finder-bubble svg{width:29px;height:29px}
.bubble-dock #worker-finder-bubble[aria-expanded=true]{border-color:#f2d1a0;background:#4b4740}
.workspace-find-panel{position:fixed;z-index:1900;width:min(385px,calc(100vw - 16px));min-height:185px;display:flex;flex-direction:column;gap:9px;padding:13px;background:#252525f7;border:1px solid #696057;border-radius:10px;box-shadow:0 16px 45px #000b;color:#f0e8da}
.workspace-find-panel header{display:flex;align-items:center;justify-content:space-between;gap:8px}
.workspace-find-panel header strong{color:#f2d5a3;font-size:14px}
.workspace-find-panel header button{padding:1px 7px;font-size:20px;line-height:1.3}
.workspace-find-panel>input{width:100%;padding:9px 10px;border:1px solid #706458;border-radius:6px;background:#1b1b1b;color:#f6eee0;font-size:13px}
.workspace-find-modes{display:flex;gap:4px;padding:3px;background:#1d1d1d;border:1px solid #54504b;border-radius:6px}
.workspace-find-modes button{flex:1;padding:6px;border-radius:4px;color:#c8c2b9;font-size:12px}
.workspace-find-modes button[aria-pressed=true]{background:#514434;color:#ffdbA3;box-shadow:inset 0 0 0 1px #b98648}
.workspace-find-status{font-size:11px;color:#beb7ac}
.workspace-find-results{min-height:0;overflow:auto;overscroll-behavior:contain;display:flex;flex-direction:column;gap:3px;padding-right:2px}
.workspace-find-results h3{margin:8px 0 3px;padding-bottom:4px;border-bottom:1px solid #59534a;color:#f1c98c;font-size:11px;font-weight:600}
.workspace-find-result{display:flex;align-items:center;gap:9px;width:100%;min-width:0;padding:7px 8px;background:#303030;border:1px solid #515151;border-radius:6px;text-align:left}
.workspace-find-result:hover,.workspace-find-result[data-active=true],.workspace-find-result:focus-visible{background:#4b4033;border-color:#d49a50}
.workspace-find-result>span:last-child{display:flex;min-width:0;flex-direction:column;gap:2px}
.workspace-find-result strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;font-weight:600;color:#f1e8d5}
.workspace-find-result small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#c0b9ae;font-size:10px}
.workspace-find-icon{display:grid;place-items:center;flex:none;width:27px;height:27px;border:1px solid #685b4b;border-radius:5px;background:#262626;color:#f1c98c;font-size:15px}
.workspace-find-empty{padding:20px 8px;text-align:center;color:#bcb5a9;font-size:12px}
.workspace-find-panel{box-sizing:border-box;overflow:hidden}
.workspace-find-panel>input{flex:none}
.workspace-find-results{flex:1;min-height:0;overflow-y:auto;scrollbar-gutter:stable;scrollbar-width:thin;scrollbar-color:#9a8466 #303030}
.workspace-find-results>*{flex:none}
@media(max-width:700px){.workspace-find-panel{width:min(385px,calc(100vw - 16px));padding:11px}}
.is-mobile-editor .workspace-find-panel{left:8px!important;right:8px!important;top:8px!important;bottom:auto!important;width:auto!important;height:min(580px,calc(var(--mobile-height,100svh) - 16px))!important;max-height:none!important}
